const connectionString = "postgresql://neondb_owner:npg_NafhUtWPF51V@ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech/neondb?sslmode=require";

async function fetchInvoiceData() {
  return new Promise((resolve, reject) => {
    try {
      const rawInput = typeof $vendor_id !== 'undefined' ? String($vendor_id) : '';

      // Match INV-001 format (with hyphen)
      const invoiceMatch = rawInput.match(/INV-?\w+/i);
      const vendorMatch = rawInput.match(/VEN-?\d+/i);

      let query, params, lookupMode;

      if (invoiceMatch) {
        lookupMode = 'invoice';
        query = `
          SELECT
            i.invoice_id,
            i.date            AS invoice_date,
            i.vendor_id,
            i.invoice_number,
            i.po_id,
            i.grn_id,
            i.invoice_amount,
            i.amount          AS invoice_amount_alt,
            i.gstin           AS invoice_gstin,
            i.approval_status,
            i.approval_limit_exceeded,
            i.department,
            i.cost_center,
            i.payment_status,
            i.quantity        AS invoice_quantity,
            po.po_amount,
            po.status         AS approval_status_po,
            po.po_date,
            po.vendor_id      AS po_vendor_id,
            po.department     AS po_department,
            po.approver,
            gr.received_amount AS grn_amount,
            gr.received_quantity,
            gr.ordered_quantity,
            gr.receipt_date,
            gr.quality_check,
            vm.vendor_name,
            vm.official_gstin AS official_gstin,
            vm.pan_number,
            vm.vendor_category,
            vm.city,
            vm.state,
            vm.risk_rating    AS vendor_risk_rating,
            vm.risk_score_numeric,
            vm.blacklist_status,
            vm.blacklisted,
            vm.shell_risk_score,
            vm.shared_director,
            vm.shared_ip_address,
            vm.gstin_status,
            vm.kyc_status
          FROM invoices i
          LEFT JOIN purchase_orders po  ON i.po_id  = po.po_id
          LEFT JOIN goods_receipts  gr  ON i.grn_id = gr.grn_id
          LEFT JOIN vendor_master   vm  ON i.vendor_id = vm.vendor_id
          WHERE i.invoice_id ILIKE $1
          LIMIT 1;
        `;
        params = [invoiceMatch[0].toUpperCase()];
      } else if (vendorMatch) {
        lookupMode = 'vendor';
        query = `
          SELECT
            i.invoice_id,
            i.date            AS invoice_date,
            i.vendor_id,
            i.invoice_number,
            i.po_id,
            i.grn_id,
            i.invoice_amount,
            i.gstin           AS invoice_gstin,
            i.approval_status,
            i.approval_limit_exceeded,
            i.department,
            po.po_amount,
            po.status         AS approval_status_po,
            gr.received_amount AS grn_amount,
            gr.received_quantity,
            gr.ordered_quantity,
            vm.vendor_name,
            vm.official_gstin AS official_gstin,
            vm.pan_number,
            vm.vendor_category,
            vm.risk_rating    AS vendor_risk_rating,
            vm.blacklisted,
            vm.shell_risk_score,
            vm.shared_director,
            vm.shared_ip_address,
            vm.gstin_status,
            vm.kyc_status
          FROM invoices i
          LEFT JOIN purchase_orders po  ON i.po_id  = po.po_id
          LEFT JOIN goods_receipts  gr  ON i.grn_id = gr.grn_id
          LEFT JOIN vendor_master   vm  ON i.vendor_id = vm.vendor_id
          WHERE i.vendor_id ILIKE $1
          ORDER BY i.date DESC
          LIMIT 20;
        `;
        params = [vendorMatch[0].toUpperCase()];
      } else {
        return resolve(JSON.stringify({
          error: "Invalid input",
          details: "Please provide an invoice ID (e.g., INV-001) or vendor ID (e.g., VEN-001).",
          raw_input: rawInput
        }, null, 2));
      }

      const postData = JSON.stringify({ query, params });
      const options = {
        hostname: 'ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech',
        port: 443,
        path: '/sql',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Neon-Connection-String': connectionString,
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      const req = https.request(options, (res) => {
        let body = '';
        res.on('data', chunk => body += chunk);
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            try {
              const parsed = JSON.parse(body);
              const rows = parsed.rows || parsed;
              if (!rows || rows.length === 0) {
                return resolve(JSON.stringify({ error: `No records found`, lookup_mode: lookupMode, lookup_value: params[0] }, null, 2));
              }
              if (lookupMode === 'invoice') {
                const row = rows[0];
                const inv = parseFloat(row.invoice_amount) || 0;
                const po  = parseFloat(row.po_amount) || 0;
                const grn = parseFloat(row.grn_amount) || 0;
                row._three_way_match_ok = (inv > 0 && po > 0 && grn > 0)
                  ? (Math.abs(inv - po) / po < 0.01 && Math.abs(inv - grn) / grn < 0.01)
                  : null;
                row._requires_enhanced_approval = inv > 100000;
                row._po_missing = !row.po_id;
                row._grn_missing = !row.grn_id;
                resolve(JSON.stringify(row, null, 2));
              } else {
                resolve(JSON.stringify({ vendor_id: params[0], invoice_count: rows.length, invoices: rows }, null, 2));
              }
            } catch (e) {
              resolve(JSON.stringify({ error: "JSON parse failed", details: e.message }));
            }
          } else {
            resolve(JSON.stringify({ error: `Neon HTTP Error ${res.statusCode}`, details: body }));
          }
        });
      });

      req.on('error', e => resolve(JSON.stringify({ error: "Network error", message: e.message })));
      req.write(postData);
      req.end();
    } catch (err) {
      resolve(JSON.stringify({ error: String(err), message: err.message }));
    }
  });
}

return await fetchInvoiceData();

