try {
    const parseFlags = (str) => {
        try {
            const match = String(str).match(/\[[\s\S]*\]/);
            if (match) return JSON.parse(match[0]);
            return [];
        } catch(e) { return []; }
    };

    let allFlags = [
        ...parseFlags($flags_2a),
        ...parseFlags($flags_2b),
        ...parseFlags($flags_2c)
    ];

    let highestSeverity = "NONE";
    const severityRank = { "CRITICAL": 4, "HIGH": 3, "MEDIUM": 2, "LOW": 1, "NONE": 0 };

    allFlags.forEach(f => {
        let s = String(f.Severity || f.severity || "LOW").toUpperCase();
        if (severityRank[s] > severityRank[highestSeverity]) {
            highestSeverity = s;
        }
    });

    // Parse policy_version from the policy_data JSON object
    let polVers = 1.0;
    try {
        const pd = typeof $policy_data === 'string' ? JSON.parse($policy_data) : $policy_data;
        polVers = parseFloat(pd.policy_version) || 1.0;
    } catch(e) { polVers = 1.0; }

    const result = {
        risk_rating: highestSeverity === "NONE" ? "LOW" : highestSeverity,
        flags_detected: allFlags,
        policy_version_applied: polVers
    };

    return JSON.stringify(result);
} catch(err) {
    return JSON.stringify({ risk_rating: "ERROR", flags_detected: [], policy_version_applied: 1.0 });
}
